// Good: message + identifiers; framework adds time/level/class/thread
log.info("Order placed: orderId={}, customerId={}, total={}",
         order.id(), order.customerId(), order.total());
// Output: 2026-06-04 10:23:45.123 INFO [http-nio-8080-exec-3] OrderService
